-- P0-01 procurement and inventory tenant referential-integrity hardening.
-- Adds tenant-scoped candidate keys and composite foreign keys for every
-- existing procurement/inventory FK whose child and parent both carry a
-- non-null tenant_id but whose original FK omitted tenant_id.
-- Existing single-column FKs remain in place; these constraints add the
-- missing same-tenant invariant while preserving the original delete action.
-- Production read-only reconciliation found zero existing cross-tenant rows
-- across these 70 relationships before this development-branch correction.
-- restaurant_inventory_units.tenant_id is nullable for shared/global units;
-- those unit references are intentionally excluded from this migration.

CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_goods_receipt_items_id ON public.restaurant_goods_receipt_items (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_goods_receipts_id ON public.restaurant_goods_receipts (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_inventory_batches_id ON public.restaurant_inventory_batches (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_inventory_categories_id ON public.restaurant_inventory_categories (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_inventory_items_id ON public.restaurant_inventory_items (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_locations_id ON public.restaurant_locations (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_order_items_id ON public.restaurant_order_items (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_productions_id ON public.restaurant_productions (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_purchase_order_items_id ON public.restaurant_purchase_order_items (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_purchase_orders_id ON public.restaurant_purchase_orders (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_purchase_requests_id ON public.restaurant_purchase_requests (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_stock_movements_id ON public.restaurant_stock_movements (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_stock_transfer_lines_id ON public.restaurant_stock_transfer_lines (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_stock_transfers_id ON public.restaurant_stock_transfers (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS restaurant_suppliers_tenant_id_id_uq ON public.restaurant_suppliers (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_stocktakes_id ON public.restaurant_stocktakes (tenant_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tenant_scope_supplier_invoices_id ON public.restaurant_supplier_invoices (tenant_id, id);
